query.base:
TS metrics-gcp.cloudsql_postgresql.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// PostgreSQL-only metric: no engine marker needed.
// Fraction (0-1) of the ~2 billion usable transaction IDs consumed since the last freeze.
// MAX(MAX_OVER_TIME) is exact across fragments; the value moves slowly, so the
// window peak is effectively the current value.
| STATS xid_util = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/postgresql/transaction_id_utilization`))
    BY database_id

breach.segment:
WHERE xid_util IS NOT NULL
| EVAL xid_used_pct = ROUND(xid_util * 100.0, 2)
// Alert threshold (percent). 70% follows Google's Cloud SQL guidance for this metric
// (example alert threshold in Google's transaction ID utilization monitoring guide);
// Google's recommender flags instances at 80%. Near 100% PostgreSQL stops accepting
// writes to prevent wraparound. Healthy instances usually sit at a low, sawtoothed level.
// Lower (e.g. 50) for an earlier warning, raise (e.g. 80) to match the recommender.
| WHERE xid_used_pct >= 70
| KEEP database_id, xid_used_pct
| SORT xid_used_pct DESC
| LIMIT 100
